-- the time budget read: p90 per gate step, queue wait per slot, test mode at commit; run in ~/.local/state/x: duckdb -f <this> ; set the since date below
create table s as select * from read_csv('gate-steps.log', delim='	', header=false, null_padding=true, ignore_errors=true, columns={'ts':'VARCHAR','load':'DOUBLE','src':'VARCHAR','ref':'VARCHAR','sha':'VARCHAR','sec':'DOUBLE','ex':'INT','cmd':'VARCHAR','cpu':'VARCHAR'});
select src, regexp_replace(cmd,'^script/test-commit.sh ','') step, count(*) n, quantile_cont(sec,.5) p50, quantile_cont(sec,.9) p90, max(sec) mx, round(quantile_cont(load,.5)) load50, sum(case when ex<>0 then 1 else 0 end) reds from s where ts >= '2026-11-07T15:40' and cmd <> 'test:twin:skipped' group by all having n>=3 order by src, n desc;
create table q as select * from read_csv('gate-queue.log', delim='\t', header=false, null_padding=true, ignore_errors=true, columns={'ts':'VARCHAR','load':'DOUBLE','slot':'VARCHAR','wait':'DOUBLE','run':'DOUBLE','ex':'INT','sess':'VARCHAR','cmd':'VARCHAR'});
select substr(ts,1,10) d, slot, count(*) n, quantile_cont(wait,.5) w50, quantile_cont(wait,.9) w90, max(wait) wmx, quantile_cont(run,.9) r90, round(max(load)) loadmx, count(distinct sess) sessions from q where ts>='2026-11-07T15:40' group by all order by d, slot;
create table c as select * from read_csv('test-commit.log', delim='\t', header=false, null_padding=true, ignore_errors=true, columns={'ts':'VARCHAR','load':'DOUBLE','br':'VARCHAR','mode':'VARCHAR','paths':'VARCHAR','sha':'VARCHAR','sec':'DOUBLE','ex':'INT','src':'VARCHAR'});
select mode, count(*) n, quantile_cont(sec,.5) p50, quantile_cont(sec,.9) p90 from c where ts>='2026-11-07T15:40' group by all order by n desc;
